-- Specialised MCQ items (coating_supervisor): gas-transmission pipelines, PRS/CGS, CP, metering and compressor stations. Sources are named in standard_ref.
-- Added 2026-10-15; approved by owner instruction (no manual review).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select v.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  ('coating_supervisor', 'معیار حفاظت کاتدی', 1, 'معیار اصلی حفاظت کاتدی خطوط فولادی مدفون در خاک نسبت به الکترود مس/سولفات مس چیست؟', '["پتانسیل On مثبت‌تر از −۵۰۰ mV","پتانسیل در بازهٔ −۳۰۰ تا −۵۰۰ mV","پتانسیل Off منفی‌تر از −۸۵۰ mV","پتانسیل منفی‌تر از −۲۰۰۰ mV"]'::jsonb, 2, 'SINGLE', null, 'معیار −۸۵۰ mV CSE با لحاظ حذف افت IR (پتانسیل پلاریزه) یا حداقل ۱۰۰ mV پلاریزاسیون است.', 'NACE SP0169 / ISO 15589-1 (Cathodic protection of pipeline systems)'),
  ('coating_supervisor', 'حد منفی پتانسیل', 2, 'حد منفی توصیه‌شدهٔ پتانسیل پلاریزه برای فولاد کربنی معمولی طبق ISO 15589-1 چقدر است؟', '["حدود −۵۰۰ mV نسبت به CSE","حدود −۲۵۰۰ mV نسبت به CSE","حدود −۸۰۰ mV نسبت به CSE","حدود −۱۲۰۰ mV نسبت به CSE"]'::jsonb, 3, 'SINGLE', null, 'پتانسیل خیلی منفی باعث تولید هیدروژن، جدایش پوشش و خطر تردی هیدروژنی می‌شود؛ حد معمول −۱٫۲ V CSE است.', 'NACE SP0169 / ISO 15589-1 (Cathodic protection of pipeline systems)'),
  ('coating_supervisor', 'مقاومت ویژه خاک', 2, 'در روش چهار الکترودی ونر با فاصلهٔ الکترودها ۲ متر، مقاومت اندازه‌گیری‌شده ۱۵ اهم است. مقاومت ویژهٔ خاک چند اهم‌متر است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"Ω·m","value":188.5,"tolPct":2}'::jsonb, 'ρ = 2π·a·R = 2π × 2 × 15 ≈ 188.5 Ω·m', 'ASTM G57 (Wenner four-pin)'),
  ('coating_supervisor', 'خوردگی خاک', 2, 'خاکی با مقاومت ویژهٔ ۸ Ω·m از نظر خورندگی چگونه طبقه‌بندی می‌شود؟', '["بسیار خورنده (Severe)","کم‌خورنده (Mild)","غیرخورنده (Non-corrosive)","خورندگی متوسط (Moderate)"]'::jsonb, 0, 'SINGLE', null, 'مقاومت ویژهٔ کمتر از حدود ۱۰ Ω·m نشانهٔ خاک بسیار خورنده است؛ مقادیر بالاتر از ۱۰۰ Ω·m کم‌خورنده‌اند.', 'NACE SP0169 – خورندگی خاک'),
  ('coating_supervisor', 'آند فداشونده', 2, 'استفادهٔ آند روی (Zn) برای خاک‌های با چه مقاومت ویژه‌ای مناسب‌تر است؟', '["مقاومت ویژهٔ زیاد (بیش از ۱۰۰ Ω·m)","مقاومت ویژهٔ کم (کمتر از حدود ۱۵ Ω·m)","مقاومت ویژهٔ متوسط (۵۰ تا ۱۰۰ Ω·m)","هر مقاومت ویژه‌ای بدون محدودیت"]'::jsonb, 1, 'SINGLE', null, 'ولتاژ محرک روی کم است (≈ ۰٫۲۵ V نسبت به فولاد) و در خاک‌های کم‌مقاومت مناسب است؛ منیزیم برای مقاومت‌های بالاتر.', 'NACE SP0169 / AWWA – آندهای فداشونده'),
  ('coating_supervisor', 'بستر آند', 1, 'هدف از پر کردن اطراف آند با ککِ ریزدانه (Coke breeze) در بستر ICCP چیست؟', '["افزایش مقاومت خاک اطراف آند","جلوگیری از عبور جریان از آند","کاهش مقاومت آند به خاک و افزایش عمر آن","افزایش وزن آند برای پایداری آن"]'::jsonb, 2, 'SINGLE', null, 'کک رسانا سطح مؤثر آند را زیاد و مقاومت بستر را کم می‌کند و جریان یکنواخت‌تر می‌دهد.', 'NACE SP0572 (Impressed current deep anode beds)'),
  ('coating_supervisor', 'مواد آند', 2, 'کدام ماده معمولاً برای آندهای بستر ICCP در پروژه‌های جدید خط لوله به‌کار می‌رود؟', '["فولاد کم‌کربن ساده ساختمانی","مس خالص صنعتی (Cu)","آلومینیوم ساختمانی (Al)","اکسید فلزی مخلوط (MMO) یا HSCI"]'::jsonb, 3, 'SINGLE', null, 'MMO/تیتانیوم و HSCI نرخ مصرف کم و عمر طولانی دارند؛ فولاد و آلومینیوم سریع مصرف می‌شوند.', 'NACE SP0169 / ISO 15589-1'),
  ('coating_supervisor', 'محاسبه جریان CP', 3, 'مساحت خارجی یک خط لوله پوشش‌دار ۳۸٬۳۰۰ مترمربع و چگالی جریان لازم ۰٫۰۲ mA/m² است. جریان مورد نیاز CP چند میلی‌آمپر است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"mA","value":766,"tolPct":2}'::jsonb, 'I = A × J = 38,300 × 0.02 = 766 mA', 'ISO 15589-1 – طراحی'),
  ('coating_supervisor', 'بازرسی CP', 2, 'هدف از برداشت پتانسیل با فاصلهٔ نزدیک (CIPS) چیست؟', '["ثبت پتانسیل On/Off در فواصل کوتاه","اندازه‌گیری ضخامت دیواره لوله","تعیین مقاومت ویژه خاک در مسیر","سنجش فشار گاز در طول خط لوله"]'::jsonb, 0, 'SINGLE', null, 'CIPS هر ۱ تا ۲٫۵ متر پتانسیل را می‌خواند تا مناطق با حفاظت ناکافی و عیوب پوشش مشخص شوند.', 'NACE SP0207 (CIS)'),
  ('coating_supervisor', 'بازرسی پوشش', 2, 'روش DCVG در خطوط مدفون برای چه هدفی به‌کار می‌رود؟', '["اندازه‌گیری فشار داخل لوله","تعیین محل و شدت عیوب پوشش","شناسایی رسوب داخلی لوله","تعیین دمای گاز در مسیر"]'::jsonb, 1, 'SINGLE', null, 'DCVG گرادیان ولتاژ ناشی از جریان در عیوب را می‌سنجد و شدت (%IR) را تخمین می‌زند.', 'NACE SP0502 (ECDA)'),
  ('coating_supervisor', 'تداخل AC', 3, 'حد ولتاژ AC روی خط لوله برای ایمنی افراد (تماس) طبق NACE SP0177 / ISO 18086 چقدر است؟', '["حدود ۵۰۰ ولت (rms)","حدود ۱۰۰ ولت (rms)","حدود ۱۵ ولت (rms)","حدود ۱ ولت (rms)"]'::jsonb, 2, 'SINGLE', null, 'برای جلوگیری از شوک، ولتاژ AC القایی روی لوله باید کمتر از حدود ۱۵ V rms باشد.', 'NACE SP0177 / ISO 18086'),
  ('coating_supervisor', 'تداخل AC', 3, 'چگالی جریان AC بالاتر از چه مقداری ریسک خوردگی AC را قابل توجه می‌کند؟', '["حدود ۰٫۰۰۱ آمپر بر مترمربع","حدود ۵۰۰ آمپر بر مترمربع","حدود ۳ آمپر بر مترمربع","حدود ۳۰ آمپر بر مترمربع"]'::jsonb, 3, 'SINGLE', null, 'طبق ISO 18086 چگالی جریان AC کمتر از ۳۰ A/m² (و در عمل کمتر از ۱۰۰ A/m² برای نقاط عیب) معیار پیشگیری است.', 'ISO 18086 (AC corrosion)'),
  ('coating_supervisor', 'اتصال عایق', 2, 'اتصال عایق (Insulating joint) در ورودی ایستگاه تقلیل فشار چه نقشی دارد؟', '["جداسازی الکتریکی خط از زمین ایستگاه","افزایش فشار مجاز لوله در ایستگاه","کاهش دمای گاز ورودی به ایستگاه","حذف نیاز به حفاظت در برابر آتش"]'::jsonb, 0, 'SINGLE', null, 'اتصال عایق جریان CP را در خط نگه می‌دارد و از اتصال به سیستم زمین ایستگاه جلوگیری می‌کند.', 'ISO 15589-1'),
  ('coating_supervisor', 'پوشش خط لوله', 2, 'حداقل اختلاف دمای سطح فلز با نقطهٔ شبنم برای اعمال پوشش چقدر است؟', '["۱ درجه پایین‌تر","۳ درجه سانتی‌گراد بالاتر","۱۰ درجه پایین‌تر","برابر نقطهٔ شبنم کافی است"]'::jsonb, 1, 'SINGLE', null, 'سطح باید حداقل ۳°C بالاتر از نقطه شبنم باشد تا رطوبت میعان نکند.', 'ISO 8502-4 / ISO 12944-7'),
  ('coating_supervisor', 'آماده‌سازی سطح', 2, 'درجهٔ تمیزکاری رایج برای اعمال پوشش FBE روی لولهٔ فولادی چیست؟', '["Sa 1 (بلاست سبک)","St 2 (برس‌کاری دستی)","Sa 2½ (بلاست خیلی دقیق)","Sa 3 برای تمام انواع پوشش"]'::jsonb, 2, 'SINGLE', null, 'FBE به سطح تمیز Sa 2½ با پروفیل زبری مناسب نیاز دارد.', 'ISO 8501-1 / ISO 21809-2 (FBE)'),
  ('coating_supervisor', 'آزمون پوشش', 2, 'برای آزمون هالیدی پوشش 3LPE با ضخامت حدود ۳ میلی‌متر کدام روش مناسب‌تر است؟', '["هالیدی اسفنج مرطوب ولتاژ پایین","آزمون ضربه با چکش","اندازه‌گیری مقاومت با اهم‌متر","هالیدی ولتاژ بالا (جرقه‌ای)"]'::jsonb, 3, 'SINGLE', null, 'پوشش ضخیم (> حدود ۰٫۵ mm) با ولتاژ بالا آزمایش می‌شود؛ اسفنج مرطوب برای فیلم نازک است.', 'NACE SP0188 / ISO 21809-1'),
  ('coating_supervisor', 'پایش CP', 2, 'طبق 49 CFR 192.465 بازدید از رکتیفایرهای CP چند بار در سال و با چه فاصلهٔ حداکثری انجام می‌شود؟', '["۶ بار در سال، فاصلهٔ حداکثر ۲٫۵ ماه","۱ بار در سال، فاصلهٔ حداکثر ۱۲ ماه","۴ بار در سال، فاصلهٔ حداکثر ۶ ماه","هر ۵ سال یک بار، فاصلهٔ ۶۰ ماه"]'::jsonb, 0, 'SINGLE', null, 'منابع جریان باید ۶ بار در سال و با فاصلهٔ حداکثر ۲٫۵ ماه بازرسی شوند؛ پایش پتانسیل خط سالانه (≤ ۱۵ ماه) است.', '49 CFR 192.465'),
  ('coating_supervisor', 'جریان سرگردان', 3, 'نوسان پتانسیل لوله در ساعات مختلف روز در نزدیکی راه‌آهن برقی DC محتمل‌ترین نشانه کدام است؟', '["کاهش مقاومت ویژهٔ خاک","جریان سرگردان DC","خرابی الکترود مرجع","تشکیل هیدرات در لوله"]'::jsonb, 1, 'SINGLE', null, 'جریان‌های DC خارجی با بار متغیر باعث نوسان پتانسیل می‌شوند و راه‌حل معمول پیوند زهکشی (Drainage bond) است.', 'NACE SP0169 – تداخل'),
  ('coating_supervisor', 'خوردگی میکروبی', 3, 'کدام باکتری با ایجاد شرایط بی‌هوازی در خاک رسی مرطوب خوردگی میکروبی فولاد را تشدید می‌کند؟', '["باکتری‌های اکسیدکنندهٔ آهن هوازی","باکتری‌های تولید مایع شوینده","باکتری‌های احیاکنندهٔ سولفات (SRB)","قارچ‌های سطحی خاک و گیاه"]'::jsonb, 2, 'SINGLE', null, 'SRB در شرایط بی‌هوازی سولفات را به H2S تبدیل و خوردگی موضعی ایجاد می‌کنند.', 'NACE SP0169 – MIC'),
  ('coating_supervisor', 'الکترود مرجع', 1, 'الکترود مرجع رایج برای اندازه‌گیری پتانسیل لوله به خاک چیست؟', '["روی خالص بدون محلول","نقره/کلرید نقره در آب مقطر","الکترود گرافیتی خشک","مس/سولفات مس اشباع (CSE)"]'::jsonb, 3, 'SINGLE', null, 'CSE با محلول سولفات مس اشباع مرجع استاندارد پتانسیل لوله به خاک در خشکی است.', 'NACE SP0169 / ISO 15589-1'),
  ('coating_supervisor', 'ایستگاه CP', 2, 'پس از نصب ترانس‌رکتیفایر جدید، اولین اقدام کنترلی قبل از وصل به بستر آند چیست؟', '["بررسی قطبیت و مقاومت مدار، شروع از کمترین ولتاژ","وصل مستقیم روی حداکثر ولتاژ خروجی","قطع اتصال به خط لوله و رها کردن کابل","بالا بردن جریان تا پتانسیل −۲ ولت"]'::jsonb, 0, 'SINGLE', null, 'قطبیت اشتباه، اتصال کوتاه یا مقاومت زیاد باعث آسیب می‌شود؛ تنظیم باید از کم شروع و پله‌ای افزایش یابد.', 'NACE SP0169 – راه‌اندازی TR'),
  ('coating_supervisor', 'عمر آند', 3, 'در طراحی بستر آند، چه عاملی بیشترین اثر مستقیم بر عمر آند HSCI دارد؟', '["رنگ آند و برچسب سازنده آن","جریان خروجی و ظرفیت مصرف آند","طول کابل رابط در سطح زمین","تعداد پیچ‌های جعبه اتصال"]'::jsonb, 1, 'SINGLE', null, 'عمر آند ∝ ظرفیت (kg) × بازده / نرخ مصرف × جریان؛ جریان بیشتر عمر را کوتاه می‌کند.', 'NACE SP0572')
) as v(job_role, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref)
where not exists (select 1 from comp_mcq_questions e where e.job_role = v.job_role and e.stem_fa = v.stem_fa);
